// EDIT ME for each run.
const p = {
  project_id: '31393214664f295f94dd86.76792605',
  day: '2026-11-13',          // UTC date to match
  tag: '131126',
  match: ['created', 'modified', 'translations'], // which dates count: created_at, modified_at (key), translations_modified_at
  pages: 37
};
const out = [];
for (let i = 1; i <= p.pages; i++) out.push({ json: Object.assign({ page: i }, p) });
return out;

const p = $('Params').first().json;
const all = [];
for (const it of $input.all()) for (const k of (it.json.keys || [])) all.push(k);
const day = p.day;
const on = (s) => typeof s === 'string' && s.indexOf(day) === 0;
const stats = { total: all.length, created: 0, modified_only: 0, translations_only: 0, archived_skipped: 0, already_tagged: 0 };
const picked = [];
for (const k of all) {
  const c = on(k.created_at), m = on(k.modified_at), t = on(k.translations_modified_at);
  if (c) stats.created++; else if (m) stats.modified_only++; else if (t) stats.translations_only++;
  const hit = (p.match.includes('created') && c) || (p.match.includes('modified') && m) || (p.match.includes('translations') && t);
  if (!hit) continue;
  if (k.is_archived) { stats.archived_skipped++; continue; }
  if ((k.tags || []).includes(p.tag)) { stats.already_tagged++; continue; }
  picked.push({ key_id: k.key_id, name: (k.key_name && (k.key_name.web || k.key_name.other)) || '', why: c ? 'created' : (m ? 'modified' : 'translations'), tags: k.tags || [] });
}
stats.to_tag = picked.length;
const out = [];
for (let i = 0; i < picked.length; i += 40) {
  const chunk = picked.slice(i, i + 40);
  out.push({ json: { project_id: p.project_id, stats, sample: i === 0 ? picked.slice(0, 200) : [], body: { keys: chunk.map(x => ({ key_id: x.key_id, tags: [p.tag], merge_tags: true })) } } });
}
if (!out.length) out.push({ json: { project_id: p.project_id, stats, sample: [], body: { keys: [] } } });
return out;

const p = $('Params').first().json;
const sel = $('Select').all();
const res = $input.all();
let ok = 0, missingTag = 0; const errors = [];
res.forEach((r, i) => {
  const b = (r.json.body) || r.json;
  if (r.json.statusCode && r.json.statusCode !== 200) errors.push({ batch: i, status: r.json.statusCode, body: r.json.body });
  for (const k of (b.keys || [])) { if ((k.tags || []).includes(p.tag)) ok++; else missingTag++; }
  if (b.errors && b.errors.length) errors.push({ batch: i, errors: b.errors });
});
return [{ json: { stats: sel[0].json.stats, sample: sel[0].json.sample, batches: sel.length, tagged_in_response: ok, missing_tag_in_response: missingTag, errors } }];
